function normalizedLimitType(value){const normalized=String(value??'NONE').trim().toUpperCase().replaceAll('-','_').replaceAll(' ','_');if(['LOWER','LOWER_LIMIT'].includes(normalized))return'LOWER_LIMIT';if(['UPPER','UPPER_LIMIT'].includes(normalized))return'UPPER_LIMIT';if(['NONE','MEASUREMENT','NOT_A_LIMIT',''].includes(normalized))return'NONE';return'UNKNOWN_LIMIT';}
