function massDefinitionFromRecord(record){const value=String(record?.values?.pl_bmassprov??'').trim();if(['Msini','M*sini'].includes(value))return'MINIMUM_MASS_M_SIN_I';if(['M*sin(i)/sin(i)','Msin(i)/sin(i)'].includes(value))return'INCLINATION_CORRECTED_MASS';if(value==='M-R relationship')return'MASS_RADIUS_RELATION_ESTIMATE';if(value==='Mass')return'SOURCE_REPORTED_MASS';return'UNSPECIFIED';}
