async function fetchGzip(url){
  const response=await fetch(url);if(!response.ok)throw new Error(`${response.status} ${response.statusText}`);
  const bytes=await response.arrayBuffer();
  if(!('DecompressionStream'in window))throw new Error('This browser does not support streaming gzip decompression. Download the JSON.gz release or use a current browser.');
  const stream=new Blob([bytes]).stream().pipeThrough(new DecompressionStream('gzip'));
  return JSON.parse(await new Response(stream).text());
}
async function ensureAtlas(){
  if(state.atlas)return state.atlas;
  if(state.atlasPromise)return state.atlasPromise;
  const status=$('#plot-accounting');if(status)status.textContent='Loading the full scientific atlas for this analysis…';
  state.atlasPromise=fetchGzip(new URL('data/sky-detections.json.gz',base)).then((atlas)=>{state.atlas=atlas;return atlas}).catch((error)=>{state.atlasPromise=null;throw error});
  return state.atlasPromise;
}
async function shaBucket(value){const hash=await crypto.subtle.digest('SHA-256',new TextEncoder().encode(value));return [...new Uint8Array(hash)].slice(0,1).map((byte)=>byte.toString(16).padStart(2,'0')).join('');}

