function showPage(page,{push=false,scroll=true}={}){const legacyDownloads=page==='downloads';if(page==='atlas')page='sky';if(legacyDownloads)page='sources';const valid=['discover','sky','object','compare','methods','sources'];page=valid.includes(page)?page:'discover';state.activePage=page;document.body.dataset.activePage=page;$$('.app-page').forEach((section)=>{section.hidden=section.dataset.page!==page});$$('[data-app-section]').forEach((item)=>{const active=item.dataset.appSection===page;active?item.setAttribute('aria-current','page'):item.removeAttribute('aria-current')});const url=new URL(location.href),restoring=state.restoringHistory;if(page==='discover'){url.searchParams.delete('section');url.searchParams.delete('object')}else url.searchParams.set('section',page);if(legacyDownloads){url.searchParams.set('data_view','downloads');setDataView('downloads')}if(!restoring){if(push)history.pushState(null,'',url);else history.replaceState(null,'',url)}if(scroll)window.scrollTo({top:0,behavior:'smooth'});updateSystemAnimation();requestAnimationFrame(()=>{if(page==='sky'){applyFilters({syncQuery:!restoring});drawSky()}if(page==='compare'&&state.compareView==='population')ensureAtlas().then(drawPlot).catch(showAnalysisError);if(page==='object'&&state.selected){renderDossier();activateObjectTab(state.objectTab)}});}
