function relativeDate(value){if(!value)return'not available';const date=new Date(value);if(!Number.isFinite(date.getTime()))return String(value);const seconds=Math.round((date.getTime()-Date.now())/1000),abs=Math.abs(seconds),formatter=new Intl.RelativeTimeFormat(undefined,{numeric:'auto'});if(abs<90)return formatter.format(seconds,'second');if(abs<5400)return formatter.format(Math.round(seconds/60),'minute');if(abs<129600)return formatter.format(Math.round(seconds/3600),'hour');if(abs<5184000)return formatter.format(Math.round(seconds/86400),'day');return date.toLocaleDateString();}
function timeMarkup(value){if(!value)return'Not available';const exact=new Date(value).toLocaleString();return`<time datetime="${escapeHtml(value)}" title="${escapeHtml(exact)}">${escapeHtml(relativeDate(value))}</time>`;}
function renderProviderHealth(){
  const node=$('#provider-health'),monitor=state.sourceMonitor;if(!node)return;if(!monitor){node.className='provider-health warning';node.innerHTML='<span class="health-dot"></span><span>Provider receipt unavailable; the atlas remains the last validated release.</span>';return;}
  const summary=monitor.summary||{},healthy=monitor.state!=='QUARANTINED'&&(summary.failed||0)===0;node.className=`provider-health ${healthy?'healthy':'warning'}`;
  const changed=summary.changed||0,failed=(summary.failed||0)+(summary.timedOut||0)+(summary.parseFailed||0)+(summary.schemaDrift||0);node.innerHTML=`<span class="health-dot"></span><span><strong>${summary.available||0} of ${summary.checked||0} provider checks responded ${timeMarkup(monitor.completedAt)}.</strong> ${changed?`${changed} provider payload${changed===1?' has':'s have'} changed; those changes remain outside the atlas until they pass reconciliation and release validation.`:'No provider change was reported in this receipt.'}${failed?` ${failed} check${failed===1?'':'s'} failed or could not be validated; the previous release remains active.`:''}</span>`;
}
function renderReleaseTimeline(){const node=$('#release-timeline');if(!node)return;const monitor=state.sourceMonitor||{},changed=monitor.summary?.changed||0,promotion=changed?'Changes detected; scientific promotion pending':monitor.datasetPromotion?.state==='NOT_IMPLEMENTED'?'No provider changes promoted by this monitor':'Promotion state not reported';node.innerHTML=`<div><span>Providers checked</span><strong>${timeMarkup(monitor.completedAt)}</strong></div><div><span>Last validated source check</span><strong>${timeMarkup(monitor.lastGoodCompletedAt)}</strong></div><div><span>Measurements in this atlas</span><strong>${timeMarkup(state.manifest.atlasGeneratedAt)}</strong></div><div><span>Website package built</span><strong>${timeMarkup(state.manifest.generatedAt)}</strong></div><div><span>New catalog rows</span><strong>${escapeHtml(promotion)}</strong></div>`;const summary=$('#update-plain-summary');if(summary)summary.innerHTML=`The public atlas contains measurements from <strong>${escapeHtml(relativeDate(state.manifest.atlasGeneratedAt))}</strong>. Providers were checked <strong>${escapeHtml(relativeDate(monitor.completedAt))}</strong>. ${changed?`The monitor found ${changed} changed provider payload${changed===1?'':'s'}; they are visible as an update state but are not yet treated as trusted measurements.`:'No provider changes were reported in the latest receipt.'}`;}

