function atlasFilters(){return{status:$('#atlas-status').value,method:$('#atlas-method').value,methodBasis:$('#method-basis')?.value||'claims',source:$('#atlas-source').value,identity:$('#identity-mode')?.value||'resolved',yearStart:Number($('#atlas-year-start').value)||-Infinity,yearEnd:Number($('#atlas-year-end').value)||Infinity};}
function updateMethodOptionCounts(){const select=$('#atlas-method');if(!select||!state.index)return;const basis=$('#method-basis')?.value||'claims',counts=basis==='primary'?coverage().primaryMethodCounts:(coverage().claimMethodCounts||coverage().methodCounts),noun=basis==='primary'?'primary records':'object claims';for(const option of select.options){if(option.value==='all'){option.textContent=basis==='primary'?'All primary methods':'All retained method claims';continue}option.textContent=`${methodLabel(option.value)} (${(counts?.[option.value]||0).toLocaleString()} ${noun})`}}
