function resultButton(d,i){return`<button id="search-option-${i}" type="button" role="option" data-object="${escapeHtml(d.objectId)}" aria-selected="false"><strong>${escapeHtml(d.name)}</strong><small>${escapeHtml(d.hostName)} · ${escapeHtml(sourceLabel(d.primarySourceId))} · ${escapeHtml(identityLabel(d.identityState))}</small><span>${escapeHtml(labels[d.normalizedStatus]||d.normalizedStatus)}</span></button>`;}
function search(){const input=$('#object-search'),box=$('#search-results'),raw=input.value,query=normalize(raw),results=findMatches(raw);if(!query){setListboxOpen(input,box,false);return[]}if(!results.length){box.innerHTML='<p class="muted search-message">No retained object matches this query. Try a host name, catalog identifier, or alias.</p>';setListboxOpen(input,box,true);return results}const systemMatches=results.filter((d)=>normalize(d.hostName)===query),systemIds=new Set(systemMatches.map((d)=>d.objectId)),others=results.filter((d)=>!systemIds.has(d.objectId));let index=0;const groups=[];if(systemMatches.length>1){groups.push(`<p class="result-group" role="presentation">${escapeHtml(systemMatches[0].hostName)} system · choose one of ${systemMatches.length} matching records</p>${systemMatches.map((d)=>resultButton(d,index++)).join('')}`);if(others.length)groups.push(`<p class="result-group" role="presentation">Other matching names and aliases</p>${others.map((d)=>resultButton(d,index++)).join('')}`)}else groups.push(results.map((d)=>resultButton(d,index++)).join(''));box.innerHTML=groups.join('');setListboxOpen(input,box,true);return results;}
function executePrimarySearch(){const input=$('#object-search'),box=$('#search-results'),results=search(),exact=exactSearchResult(input.value,results||[]);if(exact){selectObject(exact.objectId,{scroll:true});return}const first=box.querySelector('[data-object]');if(first){setActiveOption(input,box,first);first.focus();toast(`${results.length} matches found. Choose the intended object.`)}}

async function detailForObject(object){if(state.detailCache.has(object.objectId))return state.detailCache.get(object.objectId);try{const bucket=await shaBucket(object.objectId);const shard=await fetchGzip(new URL(`data/details/${bucket}.json.gz`,base));const detail=shard[object.objectId]||null;state.detailCache.set(object.objectId,detail);return detail}catch(error){console.warn('Native detail shard unavailable',error);state.detailCache.set(object.objectId,null);return null}}
async function selectObject(id,{scroll=false}={}){
  const object=objectById(id);if(!object)return;
  state.selected=object;state.selectedDetail=state.detailCache.get(object.objectId)||null;state.objectTab='overview';setQuery({object:object.objectId});setListboxOpen($('#object-search'),$('#search-results'),false);$('#object-search').value=object.name;renderSelection();renderDossier();drawSky();if(state.atlas)drawPlot();
  if(scroll)showPage('object',{push:true});
  if(!state.detailCache.has(object.objectId))state.selectedDetail=await detailForObject(object);else state.selectedDetail=state.detailCache.get(object.objectId);if(state.selectedDetail?.atlasRecord)state.selected=state.selectedDetail.atlasRecord;renderSelection();renderDossier();activateObjectTab(state.objectTab);if(scroll)requestAnimationFrame(()=>$('#object-name')?.focus());
}
function renderSelection(){const d=state.selected;if(!d){$('#selection-summary').innerHTML='<p class="eyebrow">Selected atlas record</p><h3>No world selected</h3><p class="muted">Choose a sky point or use search to open its evidence.</p>';return}$('#selection-summary').innerHTML=`<p class="eyebrow">Selected atlas record</p><h3>${escapeHtml(d.name)}</h3><p class="muted">${escapeHtml(d.hostName)}</p><dl><dt>Identity</dt><dd>${escapeHtml(identityLabel(d.identityState))}</dd><dt>Status</dt><dd>${escapeHtml(labels[d.normalizedStatus]||d.normalizedStatus)}</dd><dt>Primary method</dt><dd>${escapeHtml(methodLabel(d.methodCode))}</dd><dt>Discovery</dt><dd>${fmtYear(d.discoveryYear)}</dd><dt>Sources</dt><dd>${d.sourceIds.length}</dd><dt>Records</dt><dd>${d.sourceRecordCount.toLocaleString()}</dd></dl><button class="button primary" type="button" data-open-dossier>Open evidence dossier</button>`;}
function methodLabel(code){return state.registry?.methods.entries.find((method)=>method.code===code)?.label||code;}

