function populationCards(d){const rows=measurementRows();return Object.entries(axes).map(([key,axis])=>{const value=d.population?.[key];if(!value)return'';const assessment=assessmentForProperty(axisMeasurement[key],rows),rationale=preferredRationale(d,key,value,rows),limit=normalizedLimitType(value.limitType);return`<div class="value-card"><small>${escapeHtml(axis.label)}</small><strong>${escapeHtml(limitPrefix(value))}${fmt(value.value)} ${escapeHtml(axis.unit)}</strong><code>${escapeHtml(sourceLabel(value.sourceId))} · ${escapeHtml(value.sourceRecordId||'record id not supplied')}</code>${limit!=='NONE'?`<span class="consensus-badge" data-consensus="non-comparable">${escapeHtml(limit.replaceAll('_',' ').toLowerCase())} · not a central value</span>`:`<span class="consensus-badge" data-consensus="${escapeHtml(assessment.state)}">${escapeHtml(agreementLabels[assessment.state]||assessment.state)}</span>`}<p>${escapeHtml(rationale)}</p><p class="fineprint">${escapeHtml(value.note||'No additional projection note supplied.')}</p><button class="text-link" type="button" data-open-measurements>See alternatives and uncertainty →</button></div>`}).join('');}
