function detailNumber(keys){for(const record of state.selectedDetail?.records||[]){for(const key of keys){const value=Number(record.values?.[key]);if(Number.isFinite(value))return value}}return null;}
function objectSeed(text){let value=2166136261;for(const char of text){value^=char.charCodeAt(0);value=Math.imul(value,16777619)}return value>>>0;}
function starColor(teff,seed){if(Number.isFinite(teff)){if(teff<3700)return['#ff8a5b','#ffcf9f'];if(teff<5200)return['#ffc46b','#fff0bc'];if(teff<6500)return['#fff2c0','#ffffff'];if(teff<9000)return['#d7e7ff','#ffffff'];return['#a9c8ff','#f1f6ff']}const hues=[['#ffc46b','#fff0bc'],['#fff2c0','#ffffff'],['#d7e7ff','#ffffff'],['#ff9b6a','#ffd2b0']];return hues[seed%hues.length];}
