  let dragging=false,lastX=0,lastY=0;canvas.addEventListener('pointerdown',(event)=>{dragging=true;lastX=event.clientX;lastY=event.clientY;canvas.setPointerCapture(event.pointerId)});canvas.addEventListener('pointermove',(event)=>{if(!dragging)return;state.systemView.yaw+=(event.clientX-lastX)*.008;state.systemView.pitch=Math.max(-1.35,Math.min(1.35,state.systemView.pitch+(event.clientY-lastY)*.008));lastX=event.clientX;lastY=event.clientY;drawSystem(canvas,p)});canvas.addEventListener('pointerup',()=>{dragging=false});canvas.addEventListener('wheel',(event)=>{event.preventDefault();state.systemView.zoom=Math.max(.65,Math.min(2.2,state.systemView.zoom*Math.exp(-event.deltaY*.001)));drawSystem(canvas,p)},{passive:false});canvas.addEventListener('keydown',(event)=>{if(!['ArrowLeft','ArrowRight','ArrowUp','ArrowDown','+','-',' ','Enter'].includes(event.key))return;event.preventDefault();if(event.key==='ArrowLeft')state.systemView.yaw-=.12;if(event.key==='ArrowRight')state.systemView.yaw+=.12;if(event.key==='ArrowUp')state.systemView.pitch=Math.max(-1.35,state.systemView.pitch-.12);if(event.key==='ArrowDown')state.systemView.pitch=Math.min(1.35,state.systemView.pitch+.12);if(event.key==='+')state.systemView.zoom=Math.min(2.2,state.systemView.zoom*1.1);if(event.key==='-')state.systemView.zoom=Math.max(.65,state.systemView.zoom/1.1);if(event.key===' '||event.key==='Enter'){state.systemView.playing=!state.systemView.playing;$('#system-play').textContent=state.systemView.playing?'Pause orbit':'Play orbit';updateSystemAnimation()}drawSystem(canvas,p)});
