const uncertaintyKeys={pl_orbper:['pl_orbpererr1','pl_orbpererr2'],koi_period:['koi_period_err1','koi_period_err2'],orbital_period:['orbital_period_error_max','orbital_period_error_min'],pl_rade:['pl_radeerr1','pl_radeerr2'],koi_prad:['koi_prad_err1','koi_prad_err2'],radius:['radius_error_max','radius_error_min'],pl_bmasse:['pl_bmasseerr1','pl_bmasseerr2'],mass:['mass_error_max','mass_error_min'],mass_sini:['mass_sini_error_max','mass_sini_error_min'],pl_orbsmax:['pl_orbsmaxerr1','pl_orbsmaxerr2'],semi_major_axis:['semi_major_axis_error_max','semi_major_axis_error_min'],pl_orbeccen:['pl_orbeccenerr1','pl_orbeccenerr2'],eccentricity:['eccentricity_error_max','eccentricity_error_min']};
