function renderPlotGuide(){
  const code=$('#atlas-method').value,node=$('#plot-guide');if(!node)return;if(code==='all'){node.innerHTML='<strong>Why the cloud has this shape</strong><p>Transit surveys preferentially find larger, short-period, edge-on planets. Radial velocity more easily finds massive, short-period companions. Direct imaging favors young, hot planets on wide orbits. Microlensing is sensitive near the lensing star’s Einstein radius. Mixing these methods creates a discovery-shaped catalog—not an unbiased census.</p>';return;}
  const method=state.registry.methods.entries.find((item)=>item.code===code);node.innerHTML=`<strong>${escapeHtml(methodLabel(code))} selection effects</strong><p>${escapeHtml(method?.selectionEffects?.join(' ')||method?.limitations?.join(' ')||'This method does not sample all planet properties equally.')}</p>`;
}

