function renderComparisonCards(objects){const node=$('#comparison-cards');if(!node)return;node.hidden=!objects.length;node.innerHTML=objects.map((d)=>{const metrics=Object.entries(axes).map(([key,axis])=>comparisonProperty(`${axis.label}${axis.unit?` (${axis.unit})`:''}`,comparisonCell(d,key))).join('');return`<article class="comparison-card"><div class="comparison-card-header"><div><h3>${escapeHtml(d.name)}</h3><p class="muted">${escapeHtml(d.hostName)} · ${escapeHtml(identityLabel(d.identityState))}</p></div><span class="source-state"><i class="status-dot" style="--status:${colors[d.normalizedStatus]||colors.UNKNOWN}"></i> ${escapeHtml(labels[d.normalizedStatus]||d.normalizedStatus)}</span></div><div class="comparison-card-properties">${comparisonProperty('Primary displayed method',`<strong>${escapeHtml(methodLabel(d.methodCode))}</strong>`)}${comparisonProperty('Discovery year',`<strong>${fmtYear(d.discoveryYear)}</strong>`)}${comparisonProperty('Retained sources',`<strong>${d.sourceIds.length.toLocaleString()}</strong>`)}${metrics}</div><button class="text-link" type="button" data-compare-open="${escapeHtml(d.objectId)}">Open evidence dossier ↗</button></article>`}).join('');}
