function list(items){return`<ul>${items.map((item)=>`<li>${escapeHtml(item)}</li>`).join('')}</ul>`;}
function renderMethodDetail(){const method=state.registry.methods.entries.find((item)=>item.code===state.method),depth=$('#learning-depth').value;$$('#method-tabs button').forEach((button)=>{const active=button.dataset.method===state.method;button.classList.toggle('active',active);button.setAttribute('aria-selected',String(active));button.tabIndex=active?0:-1});$('#method-detail').setAttribute('aria-labelledby',`method-tab-${method.code}`);const claimCount=(coverage().claimMethodCounts||coverage().methodCounts||{})[method.code]||0,primaryCount=(coverage().primaryMethodCounts||{})[method.code]||0;let lab='';if(method.interactiveLesson.kind==='TRANSIT_DEPTH')lab=`<div class="lab"><h4>Idealized transit-depth lab</h4><div class="lab-grid"><label>Planet radius (R⊕)<input id="lab-rp" type="range" min="0.5" max="20" step="0.1" value="1"></label><label>Star radius (R☉)<input id="lab-rs" type="range" min="0.1" max="3" step="0.05" value="1"></label><div><small>Synthetic depth</small><output id="lab-output">84 ppm</output></div></div><p class="fineprint">Idealized δ=(Rp/R★)². No limb darkening, dilution, spots, cadence, or instrument model.</p></div>`;else if(method.interactiveLesson.kind==='RV_SEMI_AMPLITUDE')lab=`<div class="lab"><h4>Idealized radial-velocity lab</h4><div class="lab-grid"><label>Planet M sin(i) (M⊕)<input id="lab-mp" type="range" min="1" max="1000" value="318"></label><label>Period (days)<input id="lab-period" type="range" min="1" max="1000" value="365"></label><div><small>Synthetic K</small><output id="lab-output">28.4 m/s</output></div></div><p class="fineprint">Circular orbit around a 1 M☉ star; a concept calculation, not a fitted observation.</p></div>`;
  $('#method-detail').innerHTML=`<p class="method-count">${claimCount.toLocaleString()} objects retain this method claim · ${primaryCount.toLocaleString()} use it as the primary displayed method</p><h3>${escapeHtml(method.label)}</h3><p>${escapeHtml(method.detects)}</p><div class="method-columns"><section><h4>What changes in the data</h4><p>${escapeHtml(method.principalObservable)}</p>${list(method.directlyConstrained)}</section><section><h4>What it does well</h4>${list(method.strengths)}<h4>What must be assumed</h4>${list(method.requiresAssumptions)}</section><section><h4>What it favors or can confuse</h4>${list(method.limitations)}${depth==='research'?list([...method.selectionEffects,...method.falsePositives]):''}</section></div><h4>What to remember</h4>${list(method.education[depth])}<p><button class="button" type="button" data-explore-method="${escapeHtml(method.code)}">Explore objects with this method claim</button></p>${lab}`;bindLab();}
function bindLab(){const output=$('#lab-output');if(!output)return;const update=()=>{if($('#lab-rp')){const ratio=(Number($('#lab-rp').value)*.0091577)/Number($('#lab-rs').value);output.value=`${(ratio*ratio*1e6).toFixed(0)} ppm`;}else{const mp=Number($('#lab-mp').value),period=Number($('#lab-period').value);output.value=`${(28.4329*(mp/317.83)*Math.pow(period/365.25,-1/3)).toFixed(2)} m/s`;}};$('#method-detail').querySelectorAll('input').forEach((input)=>input.addEventListener('input',update));update();}

function sourceObservationMap(){return new Map((state.sourceMonitor?.observations||[]).map((item)=>[item.sourceId,item]));}
function effectiveSourceState(entry,observations=sourceObservationMap()){if(entry.state==='INGESTED')return'INGESTED';const observed=observations.get(entry.id);if(observed?.state==='AVAILABLE')return'MONITORED_AVAILABLE';if(observed)return observed.state;return entry.state;}
function friendlySourceState(entry,observation){if(entry.state==='INGESTED')return'Contributing';if(observation?.state==='AVAILABLE')return'Monitored';if(observation)return'Unavailable this attempt';return'Planned';}
function sourceCategory(entry,observations=sourceObservationMap()){const observation=observations.get(entry.id);if(entry.state==='INGESTED')return'contributing';if(observation?.state==='AVAILABLE')return'monitored';if(observation||entry.state==='BLOCKED_AUTH')return'unavailable';return'planned';}
function renderSourcesList(){const entries=state.registry.sources.entries,observations=sourceObservationMap(),counts={contributing:0,monitored:0,unavailable:0,planned:0};entries.forEach((entry)=>{counts[sourceCategory(entry,observations)]++});$('#source-summary').innerHTML=`<div><span>Declared sources</span><strong>${entries.length}</strong></div><div><span>Contributing sources</span><strong>${counts.contributing}</strong></div><div><span>Monitored only</span><strong>${counts.monitored}</strong></div><div><span>Unavailable now</span><strong>${counts.unavailable}</strong></div><div><span>Planned</span><strong>${counts.planned}</strong></div>`;filterSources();}
function sourceRow(entry,observation){const effective=effectiveSourceState(entry),friendly=friendlySourceState(entry,observation),latest=observation?`${observation.state}${Number.isFinite(observation.recordCount)?` · ${observation.recordCount.toLocaleString()} records`:''}`:'Not included in the current provider check',href=safeHref(entry.documentationUrl),contribution=entry.state==='INGESTED'?'Validated rows from this source are included in the active atlas.':observation?.state==='AVAILABLE'?'The provider responded to monitoring. Its measurements are not thereby ingested.':'No validated rows from this source entered the active atlas in this attempt.';return`<details class="source-row"><summary><span><strong>${escapeHtml(entry.name)}</strong><small>${escapeHtml(entry.authority)} · ${escapeHtml(entry.role)}</small></span><span class="source-state">${escapeHtml(friendly)}</span></summary><div class="source-row-detail"><p><strong>Release relationship:</strong> ${escapeHtml(contribution)}</p><p><strong>Latest check:</strong> ${escapeHtml(latest)}</p><p><strong>Scope:</strong> ${escapeHtml(entry.scope)}</p><p><strong>Known limitation:</strong> ${escapeHtml(entry.limitation)}</p><p><strong>Audit state:</strong> <code>${escapeHtml(effective)}</code></p>${href?`<a href="${escapeHtml(href)}" target="_blank" rel="noopener">Official documentation ↗</a>`:'<span class="muted">Documentation URL unavailable</span>'}</div></details>`;}
function filterSources(){const selected=$('#source-state-filter').value,observations=sourceObservationMap(),groups={contributing:[],monitored:[],unavailable:[],planned:[]};for(const entry of state.registry.sources.entries)groups[sourceCategory(entry,observations)].push(entry);for(const [category,entries]of Object.entries(groups)){const container=$(`#source-group-${category}`),count=$(`#source-group-${category}-count`),wrapper=$(`[data-source-group="${category}"]`);if(container)container.innerHTML=entries.map((entry)=>sourceRow(entry,observations.get(entry.id))).join('');if(count)count.textContent=String(entries.length);if(wrapper){wrapper.hidden=selected!=='all'&&selected!==category;if(selected===category)wrapper.open=true}}}

function csvEscape(value){const text=String(value??'');return/[",\n]/.test(text)?`"${text.replaceAll('"','""')}"`:text;}
function atlasRows(rows,{scope,filters,plot=null}){const metadata=makeExportMetadata({manifest:state.manifest,atlas:state.atlas,scope,filters,plot}),valueFields=['value','unit','source_id','source_record_id','definition_code','mass_definition','limit_type','selection_note'],valueHeaders=Object.keys(axes).flatMap((key)=>valueFields.map((field)=>`${key}_${field}`)),header=['public_release_generated_at','atlas_generated_at','atlas_sha256','export_scope','filter_status','filter_method','filter_method_basis','filter_identity','filter_source','filter_source_semantics','filter_year_start','filter_year_end','plot_x','plot_y','plot_x_log','plot_y_log','object_id','name','host_name','status','primary_method','all_method_claims','discovery_year','ra_deg','dec_deg','identity_state','primary_source','source_ids','source_record_count',...valueHeaders],prefix=[metadata.publicReleaseGeneratedAt,metadata.atlasGeneratedAt,metadata.atlasSha256,metadata.exportScope,metadata.filterStatus,metadata.filterMethod,metadata.filterMethodBasis,metadata.filterIdentity,metadata.filterSource,'catalog_membership_not_value_provenance',metadata.filterYearStart,metadata.filterYearEnd,metadata.plotX,metadata.plotY,metadata.plotXLog,metadata.plotYLog];return[header,...rows.map((d)=>[...prefix,d.objectId,d.name,d.hostName,d.normalizedStatus,d.methodCode,methodCodesFor(d).join('|'),d.discoveryYear,d.raDeg,d.decDeg,d.identityState,d.primarySourceId,d.sourceIds.join('|'),d.sourceRecordCount,...Object.keys(axes).flatMap((key)=>{const value=d.population[key];return value?[value.value,value.unit,value.sourceId,value.sourceRecordId,value.definitionCode,value.massDefinition||'',normalizedLimitType(value.limitType),value.note||'']:['','','','','','','','']})])];}
function download(name,content,type='text/plain'){const blob=new Blob([content],{type}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
